Problem:
A paint company makes two products from the same base: Interior paint and Exterior paint. Each litre of Interior paint takes 0.5 hours of mixing time and 0.2 kg of pigment, and earns a profit of $4. Each litre of Exterior paint takes 0.25 hours of mixing time and 0.4 kg of pigment, and earns a profit of $5. This week the company has 125 hours of mixing time and 110 kg of pigment, and it can sell at most 250 litres of Exterior paint. How many litres of each paint should it make to maximize profit?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "interior paint litres",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "exterior paint litres",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "interior paint litres",
     "coef": 4.0
    },
    {
     "var": "exterior paint litres",
     "coef": 5.0
    }
   ]
  },
  "constraints": [
   {
    "name": "mixing time",
    "terms": [
     {
      "var": "interior paint litres",
      "coef": 0.5
     },
     {
      "var": "exterior paint litres",
      "coef": 0.25
     }
    ],
    "sense": "<=",
    "rhs": 125.0
   },
   {
    "name": "pigment",
    "terms": [
     {
      "var": "interior paint litres",
      "coef": 0.2
     },
     {
      "var": "exterior paint litres",
      "coef": 0.4
     }
    ],
    "sense": "<=",
    "rhs": 110.0
   },
   {
    "name": "exterior sales cap",
    "terms": [
     {
      "var": "exterior paint litres",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 250.0
   }
  ]
 },
 "facts": {
  "objective": 1600.0,
  "values": {
   "interior paint litres": 150.0,
   "exterior paint litres": 200.0
  },
  "binding": [
   "mixing time",
   "pigment"
  ],
  "slack": {
   "mixing time": 0.0,
   "pigment": 0.0,
   "exterior sales cap": 50.0
  },
  "shadow_prices": {
   "mixing time": 4.0,
   "pigment": 10.0,
   "exterior sales cap": 0.0
  }
 }
}
